local function Log(...)
  pcall(funcLuaCommand, C.LOG, "pick_cards", ...)
end

local function Call(cmd, ...)
  local r = table.pack(pcall(funcLuaCommand, cmd, ...))
  if not r[1] then
    return nil
  end
  return table.unpack(r, 2, r.n)
end

local function Int(v)
  if type(v) ~= "number" then
    return 0
  end
  return math.floor(v + 0.5)
end

local function Hide(layer, idx)
  funcLuaMenuCommand(C.LAYER_VISIBLE, layer, idx, false)
  funcLuaMenuCommand(C.POS, layer, -4000, 4000, 0, idx)
end

-- EVT_PointerNew(): a pointer helper for menus that draw their own selectable items (docs/game/ui/mouse-support.md §5).
-- Mouse and VR's free cursor (the stick-driven «virtual mouse», CMND_SET_ENABLE_FREE_CURSOR_FOR_VIRTUAL_MOUSE) are
-- the same pointer: the engine's pointer position (558229292, screen px, y down) is read every frame and any change
-- (or the engine's «mouse moved», 3272825600) puts the menu in pointer mode; a menu arrow (CMD_UP/DOWN/LEFT/RIGHT)
-- ends it. The menu declares its zones each time it draws, from the same positions it draws with:
--   P.Begin()                              forget the zones of the last drawing
--   P.Rect(x, y, w, h, id[, edge])         top-left + size, screen px (y down)
--   P.Box(cx, cy, hw, hh, id[, edge])      centre + half sizes, screen px (y down)
--   P.Inst(layer, idx, hw, hh, id[, edge]) around a layer instance's global position (read at hit-test time)
--   (edge = -1 / 1: a scroll band; hovering it scrolls every P.REPEAT frames: ev.edge)
-- The last zone declared wins (popups / buttons drawn over cards). Per frame (Step): local ev = P.Poll() with
--   ev.moved   the pointer moved (pointer mode on)          ev.hot / ev.changed  zone id under the pointer / it changed
--   ev.click   id clicked (mouse left button, or Accept / the free cursor's A in pointer mode) on a zone
--   ev.miss    a mouse click on no zone (do nothing; Enter / A there = the menu's key Accept, pointer mode off)
--   ev.wheel   -1 up / 1 down (CMD_EVT_WHEEL_*)
--   ev.edge    -1 / 1 from a scroll band                     ev.keys   a menu arrow was pressed (pointer mode off)
--   ev.hover   the zone under the pointer, only on a frame the pointer MOVED (or was clicked): hover by movement only,
--              so a redraw / scroll / camera move under a resting pointer never re-selects (retail behaviour)
-- P.KeyStep(): the menu moved its selection itself (its own key callbacks, a polled stick / D-pad the arrows above do
-- not see): pointer mode off and the resting position taken as the baseline, so the pad owns the selection until the
-- pointer really moves again or clicks (a resting mouse would otherwise pin the selection under it).
-- Hover = move the selection to ev.hot with the keyboard highlight; ev.click = select it and decide. The menu's own
-- Accept callbacks (OnEnter / OnDecideFocus / a polled CMD_ENTER) return early while P.Owns(): in pointer mode the
-- click belongs to the pointer, so an item not under it is never activated. Zones are only declared for pickable,
-- shown items (never hidden ones). P.Forget() after a redraw under a still pointer re-focuses the zone beneath it.
EVT_PointerNew = EVT_PointerNew or function()
  local P = {zones = {}, on = false, x = nil, y = nil, hot = nil, prev = {}, edge_t = 0, REPEAT = 10}
  local MOVED, POS, GPOS, CHECK, CTRL = 3272825600, 558229292, 4002164178, 4265778440, 1332654303
  local LEFT, CLICK = 218912913 --[[CMD_EVT_MOUSE_LEFT]], 1651523701 --[[CMD_ENTER_CLICK]]
  local W_UP, W_DOWN = 1942756954 --[[CMD_EVT_WHEEL_UP]], 1623431741 --[[CMD_EVT_WHEEL_DOWN]]
  local NAV = {1197218715, 3259546669, 2765147006, 2075023265} -- CMD_UP / DOWN / LEFT / RIGHT
  local CTRLS = {CTRL, 2748927068 --[[analog-move control: the stick's menu moves]]}
  local function M(cmd, ...)
    local ok, a, b = pcall(funcLuaMenuCommand, cmd, ...)
    if ok then return a, b end
    return nil
  end
  local function In(cmd, ctrl)
    local ok, r = pcall(funcLuaCommand, CHECK, ctrl or CTRL, cmd)
    return ok and r == true
  end
  local function Edge(cmd, ctrl)
    local key = ctrl and (tostring(ctrl) .. ":" .. tostring(cmd)) or cmd
    local now = In(cmd, ctrl)
    local was = P.prev[key]
    P.prev[key] = now
    return now and not was
  end
  function P.Begin()
    P.zones = {}
  end
  function P.Rect(x, y, w, h, id, edge)
    P.zones[#P.zones + 1] = {x, y, x + w, y + h, id = id, edge = edge}
  end
  function P.Box(cx, cy, hw, hh, id, edge)
    P.zones[#P.zones + 1] = {cx - hw, cy - hh, cx + hw, cy + hh, id = id, edge = edge}
  end
  function P.Inst(layer, idx, hw, hh, id, edge)
    P.zones[#P.zones + 1] = {layer = layer, idx = idx, hw = hw, hh = hh, id = id, edge = edge}
  end
  function P.Pos()
    local x, y = M(POS)
    if type(x) == "number" and type(y) == "number" then return x, y end
    return nil
  end
  function P.At(x, y)
    if x == nil then x, y = P.x, P.y end
    if x == nil then return nil end
    for i = #P.zones, 1, -1 do
      local z = P.zones[i]
      if z.layer ~= nil then
        local gx, gy = M(GPOS, z.layer, z.idx)
        if type(gx) == "number" and type(gy) == "number" and math.abs(x - gx) <= z.hw and math.abs(-y - gy) <= z.hh then
          return z
        end
      elseif x >= z[1] and x < z[3] and y >= z[2] and y < z[4] then
        return z
      end
    end
    return nil
  end
  -- the Accept being pressed now is a pointer click: the mouse button, or Accept / A in pointer mode ON an item
  -- (Enter / A with the pointer resting on empty space is a key Accept on the current selection)
  function P.Owns()
    return In(LEFT) or (P.on and In(CLICK) and P.At() ~= nil)
  end
  -- forget the hovered zone: the next Poll reports the zone under a still pointer as changed (after a redraw)
  function P.Forget()
    P.hot = nil
  end
  function P.KeyStep()
    P.on, P.hot = false, nil
    local x, y = P.Pos()
    if x ~= nil then P.x, P.y = x, y end
  end
  function P.Reset()
    P.zones, P.on, P.hot, P.prev, P.edge_t = {}, false, nil, {}, 0
    P.x, P.y = P.Pos()
    -- a press / wheel / arrow held from the screen before is no click, no scroll, no key
    for _, c in ipairs({LEFT, CLICK, W_UP, W_DOWN}) do Edge(c) end
    for _, ctrl in ipairs(CTRLS) do
      for _, c in ipairs(NAV) do Edge(c, ctrl) end
    end
  end
  function P.Poll()
    local ev = {}
    local x, y = P.Pos()
    if x ~= nil then
      local moved = M(MOVED) == true
      if not moved and P.x ~= nil and (math.abs(x - P.x) > 1 or math.abs(y - P.y) > 1) then
        moved = true    -- the free cursor (stick) moves the pointer without the mouse's «moved» flag
      end
      P.x, P.y = x, y
      if moved then
        P.on, ev.moved = true, true
      end
    end
    for _, ctrl in ipairs(CTRLS) do
      for _, c in ipairs(NAV) do
        if Edge(c, ctrl) then
          ev.keys = true
        end
      end
    end
    if ev.keys and not ev.moved then
      P.on = false
    end
    local left, click = Edge(LEFT), Edge(CLICK)
    if left then
      P.on = true
    end
    local z = P.on and P.At() or nil
    local id = z and z.id or nil
    ev.changed = id ~= P.hot
    P.hot, ev.hot = id, id
    if z ~= nil and (ev.moved or left) then
      ev.hover = id
    end
    if left then
      if z ~= nil then
        ev.click = id
      else
        ev.miss = true                 -- a mouse click on empty space: nothing
      end
    elseif click and P.on then
      if z ~= nil then
        ev.click = id
      else
        P.on, P.hot = false, nil       -- Enter / A on empty space: the menu's key Accept takes it (selection kept)
      end
    end
    if In(W_DOWN) then
      ev.wheel = 1
    elseif In(W_UP) then
      ev.wheel = -1
    end
    if z ~= nil and z.edge ~= nil then
      P.edge_t = P.edge_t - 1
      if P.edge_t <= 0 then
        ev.edge, P.edge_t = z.edge, P.REPEAT
      end
    else
      P.edge_t = 0
    end
    return ev
  end
  return P
end
local Ptr = EVT_PointerNew()

local function Text(id)
  local ok, s = pcall(funcLuaCommand, C.TEXT_GET, id)
  if ok and type(s) == "string" then
    return s
  end
  return ""
end

local function count()
  return HEAD ~= nil and Int(HEAD.count) or 0
end

local function skip_on()
  return HEAD ~= nil and HEAD.skip == true
end

-- ---- drawing pools --------------------------------------------------------------------------------------------------
local function Place(layer, idx, x, y)
  funcLuaMenuCommand(C.POS, layer, x, -y, 0, idx)
end

local function SetColour(layer, idx, c)
  funcLuaMenuCommand(C.PRIM_COLOR, layer, idx, MESH_QUAD, c[1], c[2], c[3])
end

local function QuadTex(layer, idx, texCrc, spriteCrc, x, y, w, h)
  funcLuaMenuCommand(C.LAYER_VISIBLE, layer, idx, true)
  funcLuaMenuCommand(C.SCALE, layer, w / Q, h / Q, 1, idx)
  local ok = funcLuaMenuCommand(C.SPRITE, layer, texCrc, spriteCrc, NODE_QUAD, 0, idx)
  Place(layer, idx, x, y)
  local pt = plain_tint[layer]
  if pt ~= nil and pt[idx] ~= nil then
    pt[idx] = nil
    SetColour(layer, idx, {1, 1, 1})
  end
  return ok
end

local function Tex(path)
  if path == nil or path == "" or tex_frames[path] == -1 then
    return nil
  end
  if not tex_asked[path] then
    tex_asked[path] = true
    tex_frames[path] = 0
    funcLuaMenuCommand(C.LOAD_TEX, path)
  end
  if funcLuaCommand(C.TEX_LOADING, CRC32(path)) == true then
    tex_wait = true
    return false
  end
  return CRC32(path)
end

-- the sprite of art role `role` (a mod's), else its plain shape tinted; centre (x, y), size w x h
local function Quad(layer, idx, role, x, y, w, h)
  local a = art[role]
  if a ~= nil then
    local tc = Tex(a.atlas)
    if tc == false then
      Hide(layer, idx)
      return
    end
    if tc ~= nil and QuadTex(layer, idx, tc, a.crc, x, y, w, h) ~= false then
      return
    end
  end
  local f = FALLBACK[role] or FALLBACK_ANY
  local tc, sc = VRFW_ScreenArt.Plain(f[1])
  QuadTex(layer, idx, tc, sc, x, y, w, h)
  plain_tint[layer] = plain_tint[layer] or {}
  plain_tint[layer][idx] = f[2]
  SetColour(layer, idx, f[2])
end

-- the next plate of the pool: role, top-left (x, y), size, draw priority, alpha
local function Plate(role, x, y, w, h, priority, alpha)
  if used.plate >= N.PLATE then
    return nil
  end
  local idx = used.plate
  used.plate = used.plate + 1
  Quad(L_PLATE, idx, role, x + w / 2, y + h / 2, w, h)
  pcall(funcLuaMenuCommand, C.DRAW_PRIORITY, L_PLATE, idx, priority or LO.prio.card, true)
  pcall(funcLuaMenuCommand, C.ALPHA, L_PLATE, idx, 0, alpha or 1)
  return idx
end

-- a mod's icon (atlas + sprite) centred on (x, y)
local function Icon(atlas, sprite, x, y, size)
  if used.plate >= N.PLATE or atlas == "" or sprite == "" then
    return
  end
  local tc = Tex(atlas)
  if not tc then
    return
  end
  local idx = used.plate
  used.plate = used.plate + 1
  QuadTex(L_PLATE, idx, tc, CRC32(sprite), x, y, size, size)
  pcall(funcLuaMenuCommand, C.DRAW_PRIORITY, L_PLATE, idx, LO.prio.part, true)
  pcall(funcLuaMenuCommand, C.ALPHA, L_PLATE, idx, 0, 1)
end

-- the width of a text at `scale` (CJK letters count twice)
local function Units(s)
  local u = 0
  for ch in tostring(s or ""):gmatch("[%z\1-\127\194-\244][\128-\191]*") do
    u = u + ((ch:byte(1) or 0) >= 0xE3 and 2 or 1)
  end
  return u
end

-- the next text line of the pool: its left edge x, its middle y (light text)
local function Line(s, x, y, scale)
  if s == nil or s == "" or used.text >= N.TEXT then
    return
  end
  local idx = used.text
  used.text = used.text + 1
  funcLuaMenuCommand(C.LAYER_VISIBLE, L_TEXT, idx, true)
  funcLuaMenuCommand(C.SCALE, L_TEXT, scale, scale, 1, idx)
  funcLuaMenuCommand(C.TEXT, L_TEXT, TEXT_ON, s, idx)
  funcLuaMenuCommand(C.TEXT_VISIBLE, L_TEXT, TEXT_ON, true, idx)
  funcLuaMenuCommand(C.TEXT_VISIBLE, L_TEXT, TEXT_OFF, false, idx)
  pcall(funcLuaMenuCommand, C.DRAW_PRIORITY, L_TEXT, idx, LO.prio.text, true)
  Place(L_TEXT, idx, x - TEXT_DX * scale, y)
end

-- a line centred on cx
local function LineC(s, cx, y, scale)
  Line(s, cx - Units(s) * CHAR_W * scale / 2, y, scale)
end

-- `s` cut into lines of at most `w` px at `scale` (by words; CJK text by letters)
local function Wrap(s, w, scale)
  local max = math.max(4, math.floor(w / (WRAP_W * scale)))
  local out, cur = {}, ""
  for part in string.gmatch(s, "[^\n]+") do
    for word in string.gmatch(part, "%S+") do
      if Units(word) > max then
        for ch in word:gmatch("[%z\1-\127\194-\244][\128-\191]*") do
          if Units(cur .. ch) > max then
            out[#out + 1] = cur
            cur = ""
          end
          cur = cur .. ch
        end
      else
        local nxt = cur == "" and word or (cur .. " " .. word)
        if Units(nxt) > max and cur ~= "" then
          out[#out + 1] = cur
          cur = word
        else
          cur = nxt
        end
      end
    end
    if cur ~= "" then
      out[#out + 1] = cur
      cur = ""
    end
  end
  return out
end

-- the portrait of player card `card` centred on (x, y)
local function Face(card, x, y, size)
  if VRFW_FaceIcon == nil or used.face >= N.FACE or card == 0 then
    return
  end
  local idx = used.face
  used.face = used.face + 1
  funcLuaMenuCommand(C.LAYER_VISIBLE, L_FACE, idx, true)
  VRFW_FaceIcon.Card(L_FACE, idx, {card = card}, x, y, size)
  pcall(funcLuaMenuCommand, C.DRAW_PRIORITY, L_FACE, idx, LO.prio.part, true)
end

local function HideRest()
  for i = used.plate, used.plate_was - 1 do
    Hide(L_PLATE, i)
  end
  for i = used.text, used.text_was - 1 do
    Hide(L_TEXT, i)
  end
  for i = used.face, used.face_was - 1 do
    Hide(L_FACE, i)
    if VRFW_FaceIcon ~= nil then
      VRFW_FaceIcon.Forget(L_FACE, i)
    end
  end
  used.plate_was, used.text_was, used.face_was = used.plate, used.text, used.face
end

-- ---- data -----------------------------------------------------------------------------------------------------------
local function Load()
  HEAD = Call(CMD_CARDS, 0)
  cards = {}
  if type(HEAD) ~= "table" then
    HEAD = nil
    return
  end
  for i = 1, count() do
    local c = Call(CMD_CARDS, i)
    if type(c) ~= "table" then
      c = {kind = "text", title = "?"}
    end
    c.lines = type(c.lines) == "table" and c.lines or {}
    -- a player card: an empty name is the game's name of `card`, and {name} in its texts too
    if Int(c.card) ~= 0 then
      local _, name = Call(CMD_CHARA_INFO, c.card, 0)
      name = type(name) == "string" and name or ""
      if c.title == nil or c.title == "" then
        c.title = name
      end
      local function fill(v)
        return type(v) == "string" and (v:gsub("{name}", function() return name end)) or v
      end
      c.title, c.subtitle, c.desc, c.badge = fill(c.title), fill(c.subtitle), fill(c.desc), fill(c.badge)
      for k, l in ipairs(c.lines) do
        c.lines[k] = fill(l)
      end
    end
    cards[i] = c
  end
end

-- ---- drawing --------------------------------------------------------------------------------------------------------
local function CardX(k)
  local total = LO.view * LO.card_w + (LO.view - 1) * LO.gap
  local x0 = (1920 - total) / 2
  return x0 + (k - 1) * (LO.card_w + LO.gap)
end

local function DrawCard(i, k)
  local c = cards[i]
  local x, y, w, h = CardX(k), LO.top, LO.card_w, LO.card_h
  local cx = x + w / 2
  local on = sel == i
  if on then
    Plate("focus", x - LO.focus, y - LO.focus, w + 2 * LO.focus, h + 2 * LO.focus, LO.prio.focus)
  end
  Plate("rarity_" .. Int(c.rarity), x - LO.border, y - LO.border, w + 2 * LO.border, h + 2 * LO.border, LO.prio.frame)
  Plate(c.disabled == true and "card_disabled" or "card", x, y, w, h, LO.prio.card)
  local py = y + LO.face_y
  if c.kind == "player" then
    Face(Int(c.card), cx, py, LO.face)
  elseif c.kind == "item" then
    Plate("icon_ground", cx - LO.icon / 2 - 10, py - LO.icon / 2 - 10, LO.icon + 20, LO.icon + 20, LO.prio.part)
    Icon(tostring(c.icon_atlas or ""), tostring(c.icon_sprite or ""), cx, py, LO.icon)
  else
    Plate("band", x + 30, py - 50, w - 60, 100, LO.prio.part)
  end
  LineC(tostring(c.title or ""), cx, y + LO.name_y, 0.9)
  LineC(tostring(c.subtitle or ""), cx, y + LO.sub_y, 0.68)
  local ly = y + LO.line_y
  for _, l in ipairs(c.lines) do
    LineC(tostring(l), cx, ly, 0.62)
    ly = ly + LO.line_dy
  end
  local desc = tostring(c.desc or "")
  if desc ~= "" then
    local lines = Wrap(desc, w - 50, 0.58)
    for n = 1, math.min(#lines, LO.desc_lines) do
      local s = lines[n]
      if n == LO.desc_lines and #lines > LO.desc_lines then
        s = s .. "…"
      end
      LineC(s, cx, ly + 6, 0.58)
      ly = ly + LO.desc_dy
    end
  end
  local badge = tostring(c.badge or "")
  if badge ~= "" then
    local by = y + h - LO.badge_h - 16
    Plate("badge", x + 40, by, w - 80, LO.badge_h, LO.prio.part)
    LineC(badge, cx, by + LO.badge_h / 2, 0.72)
  end
  zones[i] = {x = cx, y = y + h / 2, hw = w / 2, hh = h / 2}
end

local function DrawAll()
  if HEAD == nil then
    return
  end
  tex_wait = false
  zones = {}
  used.plate, used.text, used.face = 0, 0, 0
  Plate("dim", 0, 0, 1920, 1080, LO.prio.dim, 0.72)
  LineC(tostring(HEAD.title or ""), 960, LO.title_y, 1.1)
  LineC(tostring(HEAD.subtitle or ""), 960, LO.subtitle_y, 0.75)
  local n = count()
  for k = 1, math.min(LO.view, n) do
    local i = first + k - 1
    if cards[i] ~= nil then
      DrawCard(i, k)
    end
  end
  if n > LO.view then
    local my = LO.top + LO.card_h / 2
    if first > 1 then
      Plate("arrow_l", CardX(1) - LO.gap - LO.arrow, my - LO.arrow / 2, LO.arrow, LO.arrow, LO.prio.part)
      zones.prev = {x = CardX(1) - LO.gap - LO.arrow / 2, y = my, hw = LO.arrow / 2, hh = LO.arrow / 2}
    end
    if first + LO.view - 1 < n then
      local xr = CardX(LO.view) + LO.card_w + LO.gap
      Plate("arrow_r", xr, my - LO.arrow / 2, LO.arrow, LO.arrow, LO.prio.part)
      zones.next = {x = xr + LO.arrow / 2, y = my, hw = LO.arrow / 2, hh = LO.arrow / 2}
    end
  end
  if skip_on() then
    local x, y = 960 - LO.skip_w / 2, LO.skip_y - LO.skip_h / 2
    if sel == n + 1 then
      Plate("skip_focus", x - 8, y - 8, LO.skip_w + 16, LO.skip_h + 16, LO.prio.focus)
    end
    Plate("skip", x, y, LO.skip_w, LO.skip_h, LO.prio.card)
    local label = tostring(HEAD.skip_text or "")
    if label == "" then
      label = Text(T_SKIP)
    end
    LineC(label, 960, LO.skip_y, 0.8)
    zones[n + 1] = {x = 960, y = LO.skip_y, hw = LO.skip_w / 2, hh = LO.skip_h / 2}
  end
  HideRest()
  funcLuaMenuCommand(C.LAYER_VISIBLE, L_CURSOR, 0, false)
  funcLuaMenuCommand(C.LAYER_VISIBLE, L_GUIDE_LINE, 0, false)
end

local function UpdateButtonGuide()
  local texts, icons, offs, keys = {T_CHOOSE}, {I_ENTER}, {18}, {K_ENTER}
  if skip_on() then
    texts[2], icons[2], offs[2], keys[2] = T_SKIP, I_BACK, 36, K_BACK
  end
  funcLuaMenuCommand(C.GUIDE_SET, MENU, L_BTN_GUIDE, texts, icons, offs, {}, {})
  funcLuaMenuCommand(C.GUIDE_CMD, MENU, L_BTN_GUIDE, keys)
  funcLuaMenuCommand(C.GUIDE_OPT, MENU, L_BTN_GUIDE, false)
end

-- ---- navigation -----------------------------------------------------------------------------------------------------
local function Select(i)
  local n = count()
  local last = skip_on() and n + 1 or n
  if i < 1 or i > last or i == sel then
    return false
  end
  sel = i
  if i <= n then
    if i < first then
      first = i
    elseif i > first + LO.view - 1 then
      first = i - LO.view + 1
    end
  end
  funcLuaCommand(C.SE, SE_OK)
  DrawAll()
  return true
end

local function Leave(result)
  ready = false
  closing = result
end

local function CloseNow()
  local result = closing
  closing = nil
  pcall(funcLuaMenuCommand, C.FREE_CURSOR, true, false, true)
  VRFW_Param.Clear(KEY_RESULT)
  VRFW_Param.Set(KEY_RESULT, result)
  funcLuaCommand(C.CLOSE_MENU, MENU)
  Log("closed, pick", result)
end

local function Decide()
  local n = count()
  if sel == n + 1 and skip_on() then
    funcLuaCommand(C.SE, SE_BACK)
    Log("skip")
    Leave(0)
    return
  end
  local c = cards[sel]
  if c == nil or c.disabled == true then
    funcLuaCommand(C.SE, SE_NG)
    return
  end
  funcLuaCommand(C.SE, SE_DECIDE)
  Log("pick", sel)
  Leave(sel)
end

local function Back()
  if not skip_on() then
    funcLuaCommand(C.SE, SE_NG)
    return
  end
  funcLuaCommand(C.SE, SE_BACK)
  Log("back: skip")
  Leave(0)
end

local function Move(dir)
  local n = count()
  if dir == "LEFT" then
    if sel <= n then Select(sel - 1) end
  elseif dir == "RIGHT" then
    if sel < n then Select(sel + 1) end
  elseif dir == "DOWN" then
    if skip_on() and sel <= n then Select(n + 1) end
  elseif dir == "UP" then
    if sel == n + 1 then Select(math.min(first, n)) end
  end
end

-- the polled pad, for a press no callback reported (as the pose row screen): acts 2 frames after the press
local KEYS = {NAV = {LEFT = 2765147006, RIGHT = 2075023265, UP = 1197218715, DOWN = 3259546669, ENTER = 1981080283,
              BACK = 3011112225}, held = {}, press = {}, cb = {}, frame = 0}
local function KeyOn(k)
  for _, ctrl in ipairs({1332654303 --[[MENU_CTRL]], 2748927068 --[[MENU_CTRL_WITH_ANALOG_MOVE_FOCUS]]}) do
    local ok, r = pcall(funcLuaCommand, C.CHECK_INPUT, ctrl, k)
    if ok and r == true then
      return true
    end
  end
  return false
end

local function Act(name)
  if name == "ENTER" then
    Decide()
  elseif name == "BACK" then
    Back()
  else
    Ptr.KeyStep()
    Move(name)
  end
end

local function PollKeys(free)
  for name, cmd in pairs(KEYS.NAV) do
    local on = KeyOn(cmd)
    if on and not KEYS.held[name] then
      KEYS.press[name] = KEYS.frame
    elseif not on then
      KEYS.press[name] = nil
    end
    KEYS.held[name] = on
    local p = KEYS.press[name]
    if p ~= nil and free and KEYS.frame - p == 2 and (KEYS.cb[name] or -100) < p - 2 then
      Act(name)
    end
  end
end

local function PollPointer()
  Ptr.Begin()
  for id, z in pairs(zones) do
    Ptr.Box(z.x, z.y, z.hw, z.hh, id)
  end
  local ev = Ptr.Poll()
  if evt_co ~= nil or not ready or open_guard > 0 then
    return
  end
  if type(ev.hover) == "number" and ev.hover ~= sel then
    Select(ev.hover)
  end
  if ev.click == "prev" or ev.click == "next" then
    KEYS.cb.ENTER = KEYS.frame
    Move(ev.click == "prev" and "LEFT" or "RIGHT")
  elseif type(ev.click) == "number" then
    KEYS.cb.ENTER = KEYS.frame
    Select(ev.click)
    Decide()
  elseif type(ev.wheel) == "number" then
    Move(ev.wheel < 0 and "LEFT" or "RIGHT")
  end
end

-- ---- callbacks ------------------------------------------------------------------------------------------------------
function OnInit()
  VRFW_Param.Clear(KEY_RESULT)
  art, plain_tint = VRFW_ScreenArt.Get(ART_SCREEN), {}
  for _, path in ipairs(VRFW_ScreenArt.Atlases(ART_SCREEN)) do
    Tex(path)
  end
  ready, open_guard, closing, zones = false, 20, nil, {}
  used = {plate = 0, text = 0, face = 0, plate_was = N.PLATE, text_was = N.TEXT, face_was = N.FACE}
  if VRFW_FaceIcon ~= nil then
    VRFW_FaceIcon.Forget(L_FACE)
  end
  Load()
  local n = count()
  sel = HEAD ~= nil and math.max(1, math.min(n, Int(HEAD.focus))) or 1
  first = math.max(1, math.min(sel, n - LO.view + 1))
  Log("open", n, "card(s), skip", tostring(skip_on()))
end

local function OpenOwnLayers()
  for i = 0, N.PLATE - 1 do
    funcLuaMenuCommand(C.OPEN_LAYER, L_PLATE, i)
  end
  for i = 0, N.TEXT - 1 do
    funcLuaMenuCommand(C.OPEN_LAYER, L_TEXT, i)
  end
  for i = 0, N.FACE - 1 do
    funcLuaMenuCommand(C.OPEN_LAYER, L_FACE, i)
  end
end

function OnSetupLayer(a1, a2)
  if a1 == L_HEADER then
    funcLuaMenuCommand(C.LAYER_VISIBLE, L_HEADER, 0, false)
    OpenOwnLayers()
  elseif a1 == L_ROW or a1 == L_TEXT then
    funcLuaMenuCommand(C.TEXT, a1, TEXT_ON, "", a2)
    funcLuaMenuCommand(C.TEXT, a1, TEXT_OFF, "", a2)
    funcLuaMenuCommand(C.TEXT_VISIBLE, a1, TEXT_ON, false, a2)
    funcLuaMenuCommand(C.TEXT_VISIBLE, a1, TEXT_OFF, false, a2)
    for _, m in ipairs(ROW_MESHES) do
      funcLuaMenuCommand(C.MESH_VISIBLE, a1, m, false, a2)
    end
    funcLuaMenuCommand(C.ATTACH_TRACE, a1, a2, CUR, false)
    if a1 ~= L_ROW then
      Hide(a1, a2)
    end
  elseif a1 == L_PLATE or a1 == L_FACE then
    Hide(a1, a2)
  elseif a1 == L_RETAIL_BG or a1 == L_GUIDE_LINE then
    funcLuaMenuCommand(C.LAYER_VISIBLE, a1, 0, false)
  elseif a1 == L_BTN_GUIDE then
    UpdateButtonGuide()
  end
end

function OnOpenLayer(a1, a2)
  if a1 == L_ROW and a2 == 0 then
    funcLuaMenuCommand(C.LAYER_VISIBLE, L_CURSOR, 0, false)
    funcLuaMenuCommand(C.FOCUS_ENABLE, a1, true)
    funcLuaMenuCommand(C.LIST_NUM, a1, 1)
    funcLuaMenuCommand(C.FOCUS_SET, a1, 0)
    funcLuaMenuCommand(C.ATTACH_TRACE, a1, 0, CUR, false)
    funcLuaMenuCommand(C.POS, a1, -4000, 4000, 0, 0)
    funcLuaMenuCommand(C.LAYER_VISIBLE, L_RETAIL_BG, 0, false)
    funcLuaMenuCommand(C.LAYER_VISIBLE, L_HEADER, 0, false)
    if HEAD == nil then
      Log("open: no cards set: closing")
      Leave(0)
      return
    end
    UpdateButtonGuide()
    DrawAll()
    Ptr.Reset()
    pcall(funcLuaMenuCommand, C.FREE_CURSOR, true, false, true)
    ready = true
  elseif a1 == L_HEADER or a1 == L_RETAIL_BG or a1 == L_GUIDE_LINE then
    funcLuaMenuCommand(C.LAYER_VISIBLE, a1, 0, false)
  end
end

function OnDecideFocus(a1, a2)
  KEYS.cb.ENTER = KEYS.frame
  if evt_co ~= nil or not ready or open_guard > 0 or Ptr.Owns() then
    return
  end
  Decide()
end

function OnEnter(a1, a2)
  KEYS.cb.ENTER = KEYS.frame
  if a1 == L_BTN or a1 == L_RET then
    return 1
  end
  OnDecideFocus(a1, a2)
end

function OnFunction(a1, a2)
  local id = a1
  if a1 ~= FN.LEFT and a1 ~= FN.RIGHT and a1 ~= FN.UP and a1 ~= FN.DOWN then
    id = a2
  end
  local name = (id == FN.LEFT and "LEFT") or (id == FN.RIGHT and "RIGHT") or (id == FN.UP and "UP")
    or (id == FN.DOWN and "DOWN") or nil
  if name == nil then
    return
  end
  KEYS.cb[name] = KEYS.frame
  if evt_co ~= nil or not ready then
    return 1
  end
  Ptr.KeyStep()
  Move(name)
  return 1
end

function OnBack(a1)
  KEYS.cb.BACK = KEYS.frame
  if evt_co ~= nil or not ready or open_guard > 0 then
    return 1
  end
  Back()
  return 1
end

function Step()
  if closing ~= nil then
    CloseNow()
    return
  end
  if not ready then
    return
  end
  if open_guard > 0 then
    open_guard = open_guard - 1
  end
  -- a declared atlas / a card's icon still loading: redraw once it is in (600 frames at most)
  if tex_wait then
    local still = false
    for path, f in pairs(tex_frames) do
      if f >= 0 then
        if funcLuaCommand(C.TEX_LOADING, CRC32(path)) == true then
          tex_frames[path] = f + 1 > 600 and -1 or f + 1
          still = still or f + 1 <= 600
        else
          tex_frames[path] = -2
        end
      end
    end
    if not still then
      DrawAll()
    end
  end
  if VRFW_FaceIcon ~= nil and VRFW_FaceIcon.Pending() then
    VRFW_FaceIcon.Settle()
  end
  PollPointer()
  KEYS.frame = KEYS.frame + 1
  local free = evt_co == nil and open_guard <= 0 and funcLuaCommand(C.MSG_BUSY) ~= true
  PollKeys(free)
end
